def is_sorted(arr):
    for i in range(1, len(arr)):
        if arr[i] < arr[i-1]:
            return False
    return True

def remove_duplicates(nums):
    if not nums: return 0
    i = 0
    for j in range(1, len(nums)):
        if nums[j] != nums[i]:
            i += 1
            nums[i] = nums[j]
    return i + 1

def move_zeroes(nums):
    i = 0
    for j in range(len(nums)):
        if nums[j] != 0:
            nums[i], nums[j] = nums[j], nums[i]
            i += 1

def linear_search(arr, target):
    for i, x in enumerate(arr):
        if x == target:
            return i
    return -1

def union_sorted(a, b):
    i, j = 0, 0
    result = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            if not result or result[-1] != a[i]:
                result.append(a[i])
            i += 1
        else:
            if not result or result[-1] != b[j]:
                result.append(b[j])
            j += 1
    while i < len(a):
        if not result or result[-1] != a[i]:
            result.append(a[i])
        i += 1
    while j < len(b):
        if not result or result[-1] != b[j]:
            result.append(b[j])
        j += 1
    return result

def intersection(a, b):
    i, j = 0, 0
    result = []
    while i < len(a) and j < len(b):
        if a[i] < b[j]:
            i += 1
        elif a[i] > b[j]:
            j += 1
        else:
            if not result or result[-1] != a[i]:
                result.append(a[i])
            i += 1
            j += 1
    return result

def missing_number(nums):
    n = len(nums) + 1
    expected = n * (n + 1) // 2
    return expected - sum(nums)

def max_ones(nums):
    mx = cur = 0
    for x in nums:
        if x == 1:
            cur += 1
            mx = max(mx, cur)
        else:
            cur = 0
    return mx

def single_number(nums):
    result = 0
    for x in nums:
        result ^= x
    return result

def longest_subarray_k(arr, k):
    left = 0
    cur = 0
    mx = 0
    for right in range(len(arr)):
        cur += arr[right]
        while cur > k and left <= right:
            cur -= arr[left]
            left += 1
        if cur == k:
            mx = max(mx, right - left + 1)
    return mx

def longest_subarray_k_mixed(arr, k):
    seen = {0: -1}
    cur = 0
    mx = 0
    for i, x in enumerate(arr):
        cur += x
        if cur - k in seen:
            mx = max(mx, i - seen[cur - k])
        if cur not in seen:
            seen[cur] = i
    return mx

def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []

def sort_colors(nums):
    low, mid, high = 0, 0, len(nums) - 1
    while mid <= high:
        if nums[mid] == 0:
            nums[low], nums[mid] = nums[mid], nums[low]
            low += 1
            mid += 1
        elif nums[mid] == 1:
            mid += 1
        else:
            nums[mid], nums[high] = nums[high], nums[mid]
            high -= 1

def majority_element(nums):
    candidate = nums[0]
    count = 1
    for x in nums[1:]:
        if x == candidate:
            count += 1
        else:
            count -= 1
            if count == 0:
                candidate = x
                count = 1
    return candidate

def max_subarray(nums):
    cur = mx = nums[0]
    for x in nums[1:]:
        cur = max(x, cur + x)
        mx = max(mx, cur)
    return mx

def rearrange(arr):
    pos = [x for x in arr if x >= 0]
    neg = [x for x in arr if x < 0]
    result = []
    for i in range(max(len(pos), len(neg))):
        if i < len(pos): result.append(pos[i])
        if i < len(neg): result.append(neg[i])
    return result

def is_anagram(s, t):
    if len(s) != len(t): return False
    from collections import Counter
    return Counter(s) == Counter(t)

def group_anagrams(strs):
    from collections import defaultdict
    groups = defaultdict(list)
    for s in strs:
        key = ''.join(sorted(s))
        groups[key].append(s)
    return list(groups.values())

def top_k_frequent(nums, k):
    from collections import Counter
    import heapq
    count = Counter(nums)
    return heapq.nlargest(k, count.keys(), key=count.get)

def is_valid_sudoku(board):
    rows, cols, boxes = [set() for _ in range(9)], [set() for _ in range(9)], [set() for _ in range(9)]
    for i in range(9):
        for j in range(9):
            v = board[i][j]
            if v == '.': continue
            box_idx = (i // 3) * 3 + j // 3
            if v in rows[i] or v in cols[j] or v in boxes[box_idx]:
                return False
            rows[i].add(v)
            cols[j].add(v)
            boxes[box_idx].add(v)
    return True

def longest_consecutive(nums):
    s = set(nums)
    mx = 0
    for x in s:
        if x - 1 not in s:
            cur = x
            length = 1
            while cur + 1 in s:
                cur += 1
                length += 1
            mx = max(mx, length)
    return mx

def generate_pascal(n):
    result = []
    for i in range(n):
        row = [1] * (i+1)
        for j in range(1, i):
            row[j] = result[i-1][j-1] + result[i-1][j]
        result.append(row)
    return result

def set_zeroes(matrix):
    m, n = len(matrix), len(matrix[0])
    first_row = any(matrix[0][j] == 0 for j in range(n))
    first_col = any(matrix[i][0] == 0 for i in range(m))
    for i in range(1, m):
        for j in range(1, n):
            if matrix[i][j] == 0:
                matrix[i][0] = 0
                matrix[0][j] = 0
    for i in range(1, m):
        for j in range(1, n):
            if matrix[i][0] == 0 or matrix[0][j] == 0:
                matrix[i][j] = 0
    if first_row:
        for j in range(n): matrix[0][j] = 0
    if first_col:
        for i in range(m): matrix[i][0] = 0

def rotate(matrix):
    n = len(matrix)
    for i in range(n):
        for j in range(i+1, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]
    for row in matrix:
        row.reverse()

def spiral_order(matrix):
    result = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1
    while top <= bottom and left <= right:
        for j in range(left, right+1): result.append(matrix[top][j])
        top += 1
        for i in range(top, bottom+1): result.append(matrix[i][right])
        right -= 1
        if top <= bottom:
            for j in range(right, left-1, -1): result.append(matrix[bottom][j])
            bottom -= 1
        if left <= right:
            for i in range(bottom, top-1, -1): result.append(matrix[i][left])
            left += 1
    return result

def merge_intervals(intervals):
    intervals.sort(key=lambda x: x[0])
    result = []
    for iv in intervals:
        if result and iv[0] <= result[-1][1]:
            result[-1][1] = max(result[-1][1], iv[1])
        else:
            result.append(iv)
    return result

def merge(nums1, m, nums2, n):
    i, j, k = m-1, n-1, m+n-1
    while j >= 0:
        if i >= 0 and nums1[i] > nums2[j]:
            nums1[k] = nums1[i]
            i -= 1
        else:
            nums1[k] = nums2[j]
            j -= 1
        k -= 1

def merge_overlap(intervals):
    intervals.sort()
    merged = []
    for iv in intervals:
        if merged and iv[0] <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], iv[1])
        else:
            merged.append(iv)
    return merged

def selection_sort(arr):
    n = len(arr)
    for i in range(n):
        mn = i
        for j in range(i+1, n):
            if arr[j] < arr[mn]: mn = j
        arr[i], arr[mn] = arr[mn], arr[i]
    return arr

def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        swapped = False
        for j in range(n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
                swapped = True
        if not swapped: break
    return arr

def insertion_sort(arr):
    for i in range(1, len(arr)):
        key = arr[i]
        j = i - 1
        while j >= 0 and arr[j] > key:
            arr[j+1] = arr[j]
            j -= 1
        arr[j+1] = key
    return arr

def merge_sort(arr):
    if len(arr) <= 1: return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)

def merge(a, b):
    result = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i]); i += 1
        else:
            result.append(b[j]); j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return result

def quick_sort(arr, lo=0, hi=None):
    if hi is None: hi = len(arr) - 1
    if lo < hi:
        p = partition(arr, lo, hi)
        quick_sort(arr, lo, p - 1)
        quick_sort(arr, p + 1, hi)

def partition(arr, lo, hi):
    pivot = arr[hi]
    i = lo - 1
    for j in range(lo, hi):
        if arr[j] <= pivot:
            i += 1
            arr[i], arr[j] = arr[j], arr[i]
    arr[i+1], arr[hi] = arr[hi], arr[i+1]
    return i + 1

def sort_by_frequency(arr):
    from collections import Counter
    counts = Counter(arr)
    return sorted(arr, key=lambda x: (-counts[x], x))

def find_min(nums):
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] > nums[hi]:
            lo = mid + 1
        else:
            hi = mid
    return nums[lo]

def search_rotated(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target: return mid
        if nums[lo] <= nums[mid]:  # left half sorted
            if nums[lo] <= target < nums[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:  # right half sorted
            if nums[mid] < target <= nums[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1

def find_kth_positive(arr, k):
    lo, hi = 0, len(arr)
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] - mid - 1 < k:
            lo = mid + 1
        else:
            hi = mid
    return lo + k

def aggressive_cows(stalls, k):
    stalls.sort()
    def can_place(dist):
        count = 1
        last = stalls[0]
        for s in stalls[1:]:
            if s - last >= dist:
                count += 1
                last = s
                if count >= k: return True
        return False
    lo, hi = 1, stalls[-1] - stalls[0]
    while lo <= hi:
        mid = (lo + hi) // 2
        if can_place(mid):
            lo = mid + 1
        else:
            hi = mid - 1
    return hi

def allocate_pages(books, m):
    def can_alloc(max_pages):
        students, cur = 1, 0
        for b in books:
            if cur + b <= max_pages:
                cur += b
            else:
                students += 1
                cur = b
                if students > m: return False
        return True
    lo, hi = max(books), sum(books)
    while lo < hi:
        mid = (lo + hi) // 2
        if can_alloc(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

def find_median_sorted_arrays(a, b):
    if len(a) > len(b): a, b = b, a
    m, n = len(a), len(b)
    lo, hi = 0, m
    while lo <= hi:
        i = (lo + hi) // 2
        j = (m + n + 1) // 2 - i
        a_left = a[i-1] if i > 0 else float('-inf')
        a_right = a[i] if i < m else float('inf')
        b_left = b[j-1] if j > 0 else float('-inf')
        b_right = b[j] if j < n else float('inf')
        if a_left <= b_right and b_left <= a_right:
            if (m+n) % 2 == 0:
                return (max(a_left, b_left) + min(a_right, b_right)) / 2
            return max(a_left, b_left)
        elif a_left > b_right:
            hi = i - 1
        else:
            lo = i + 1

def remove_outer(s):
    result = []
    depth = 0
    for c in s:
        if c == '(':
            if depth > 0: result.append(c)
            depth += 1
        else:
            depth -= 1
            if depth > 0: result.append(c)
    return ''.join(result)

def largest_odd_number(s):
    for i in range(len(s)-1, -1, -1):
        if int(s[i]) % 2 == 1:
            return s[:i+1]
    return ''

def is_isomorphic(s, t):
    if len(s) != len(t): return False
    s_to_t, t_to_s = {}, {}
    for a, b in zip(s, t):
        if (a in s_to_t and s_to_t[a] != b) or (b in t_to_s and t_to_s[b] != a):
            return False
        s_to_t[a] = b
        t_to_s[b] = a
    return True
